package com.orbit.life;
import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.webkit.*;
import android.widget.*;
import android.text.InputType;
import android.security.keystore.*;
import android.util.Base64;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import org.json.*;
public class MainActivity extends Activity {
 private WebView web;private final ExecutorService executor=Executors.newSingleThreadExecutor();private String pendingContent,pendingImport;private static final String ORIGIN="https://orbit.local/",ALIAS="orbit.deepseek.key";
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(12,16,18));getWindow().setNavigationBarColor(Color.rgb(12,16,18));
 web=new WebView(this);web.setBackgroundColor(Color.rgb(12,16,18));setContentView(web);
 if(Build.VERSION.SDK_INT>=35){web.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});}
 WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportMultipleWindows(false);
 web.addJavascriptInterface(new Bridge(),"OrbitNative");web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){return !req.getUrl().toString().startsWith(ORIGIN);}
 @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){String url=req.getUrl().toString();if(!url.startsWith(ORIGIN))return empty();try{String file=req.getUrl().getPath();if(file==null||file.equals("/"))file="/local.html";if(file.contains(".."))return empty();String mime=file.endsWith(".html")?"text/html":file.endsWith(".js")?"text/javascript":file.endsWith(".css")?"text/css":file.endsWith(".ttf")?"font/ttf":file.endsWith(".svg")?"image/svg+xml":"application/octet-stream";return new WebResourceResponse(mime,mime.startsWith("text/")?"UTF-8":null,getAssets().open("www"+file));}catch(Exception e){return empty();}}
 });web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsConfirm(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}@Override public boolean onJsAlert(WebView view,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("知道了",(d,w)->result.confirm()).show();return true;}});
 web.loadUrl(ORIGIN);
 }
 private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}
 private SecretKey encryptionKey()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))return ((KeyStore.SecretKeyEntry)store.getEntry(ALIAS,null)).getSecretKey();KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}
 private void saveKey(String key)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,encryptionKey());String encrypted=Base64.encodeToString(c.doFinal(key.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);getSharedPreferences("ai",MODE_PRIVATE).edit().putString("cipher",encrypted).putString("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).apply();}
 private String readKey()throws Exception{android.content.SharedPreferences prefs=getSharedPreferences("ai",MODE_PRIVATE);String encrypted=prefs.getString("cipher",null);if(encrypted==null)throw new Exception("请先点击 AI 设置配置 DeepSeek 密钥");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,encryptionKey(),new GCMParameterSpec(128,Base64.decode(prefs.getString("iv",""),Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(encrypted,Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 private void answer(String id,String result){runOnUiThread(()->{if(web!=null)web.evaluateJavascript("window.__orbitNativeResult&&window.__orbitNativeResult("+JSONObject.quote(id)+","+result+")",null);});}
 private void error(String id,String message){try{answer(id,new JSONObject().put("error",message).toString());}catch(Exception ignored){}}
 private String readLimited(InputStream in,int max)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int count,total=0;while((count=input.read(buffer))!=-1){total+=count;if(total>max)throw new Exception("内容太大");out.write(buffer,0,count);}return out.toString("UTF-8");}}
 public class Bridge {
 @JavascriptInterface public boolean configured(){return getSharedPreferences("ai",MODE_PRIVATE).contains("cipher");}
 @JavascriptInterface public void configure(){runOnUiThread(()->{EditText field=new EditText(MainActivity.this);field.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);field.setSingleLine(true);field.setHint("在这里输入新的 DeepSeek API Key");LinearLayout box=new LinearLayout(MainActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(40,12,40,12);TextView hint=new TextView(MainActivity.this);hint.setText("密钥只加密保存在这台手机，不上传 GitHub。聊天和你要求查询的应用记录会发送至 DeepSeek。电脑密钥不会随 APK 复制。");hint.setTextSize(13);box.addView(hint);box.addView(field);AlertDialog dialog=new AlertDialog.Builder(MainActivity.this).setTitle("配置团团的智慧").setView(box).setNegativeButton("取消",null).setPositiveButton("加密保存",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String key=field.getText().toString().trim();if(key.length()<12||key.length()>512){field.setError("请检查密钥");return;}try{saveKey(key);field.setText("");dialog.dismiss();web.evaluateJavascript("window.dispatchEvent(new Event('orbit:configured'))",null);Toast.makeText(MainActivity.this,"已加密保存",Toast.LENGTH_SHORT).show();}catch(Exception e){field.setError("保存失败，请重试");}}));dialog.show();});}
 @JavascriptInterface public void saveDocument(String name,String content){if(content==null||content.length()>2000000)return;runOnUiThread(()->{if(pendingContent!=null){Toast.makeText(MainActivity.this,"请先完成上一次保存",Toast.LENGTH_SHORT).show();return;}pendingContent=content;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(name.endsWith(".csv")?"text/csv":"application/json");i.putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^a-zA-Z0-9._-]","_"));try{startActivityForResult(i,201);}catch(Exception e){pendingContent=null;Toast.makeText(MainActivity.this,"无法打开文件选择器",Toast.LENGTH_SHORT).show();}});}
 @JavascriptInterface public void request(String id,String raw){if(raw==null||raw.length()>200000)return;executor.execute(()->{try{JSONObject request=new JSONObject(raw);String type=request.getString("type");if(type.equals("import")){runOnUiThread(()->{if(pendingImport!=null){error(id,"请先完成上一次导入");return;}pendingImport=id;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");try{startActivityForResult(i,202);}catch(Exception e){pendingImport=null;error(id,"无法打开文件选择器");}});return;}if(!type.equals("complete"))throw new Exception("不支持的操作");String key=readKey();JSONObject body=request.getJSONObject("body");body.put("model","deepseek-flash");body.put("max_tokens",1200);body.put("stream",false);HttpURLConnection connection=(HttpURLConnection)new URL("https://api.deepseek.com/chat/completions").openConnection();try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(45000);connection.setRequestMethod("POST");connection.setRequestProperty("Authorization","Bearer "+key);connection.setRequestProperty("Content-Type","application/json");connection.setDoOutput(true);try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=connection.getResponseCode();if(code!=200)throw new Exception(code==401?"密钥无效，请重新配置":code==402?"DeepSeek余额不足":code==429?"请求繁忙，请稍后重试":"DeepSeek暂时不可用（"+code+"）");String response=readLimited(connection.getInputStream(),2000000).replace(key,"[已隐藏]");answer(id,new JSONObject(response).toString());}finally{connection.disconnect();}}catch(Exception e){String message=e instanceof java.net.SocketTimeoutException?"网络连接超时，请重试":e.getMessage();if(message==null||message.length()>120||message.contains("https:"))message="网络连接失败，请稍后重试";error(id,message);}});}
 }
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==201){String content=pendingContent;pendingContent=null;if(resultCode==RESULT_OK&&data!=null&&content!=null){executor.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){out.write(content.getBytes(StandardCharsets.UTF_8));runOnUiThread(()->Toast.makeText(this,"文件已保存",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"保存失败",Toast.LENGTH_SHORT).show());}});}}else if(requestCode==202){String id=pendingImport;pendingImport=null;if(id==null)return;if(resultCode!=RESULT_OK||data==null){error(id,"已取消导入");return;}executor.execute(()->{try{String content=readLimited(getContentResolver().openInputStream(data.getData()),2000000);answer(id,new JSONObject().put("content",content).toString());}catch(Exception e){error(id,"无法读取备份文件");}});}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("OrbitNative");web.destroy();web=null;}executor.shutdownNow();super.onDestroy();}
}
